#[test]
fn compose_summary_same_start_end_date_single_date_alias() {
    let ts = chrono::Utc.timestamp_millis_opt(1_700_000_000_000).unwrap();
    let input = SummaryComposeInput {
        summary_id: "summary:L1:sameday",
        tree_kind: SummaryTreeKind::Global,
        tree_id: "t1",
        tree_scope: "global",
        level: 1,
        child_ids: &["child-a".to_string()],
        child_basenames: None,
        child_count: 1,
        time_range_start: ts,
        time_range_end: ts,
        sealed_at: ts,
        body: "day recap",
    };
    let composed = compose_summary_md(&input);
    let alias_line = composed
        .front_matter
        .lines()
        .find(|l| l.contains("L1") && l.contains("global digest"))
        .expect("alias line must be present");
    let date_str = ts.format("%Y-%m-%d").to_string();
    assert!(alias_line.contains(&date_str), "got: {alias_line}");
    assert!(!alias_line.contains('\u{2013}'), "got: {alias_line}");
}

#[test]
fn scope_short_label_two_participants() {
    let label = scope_short_label("gmail:alice@x.com|bob@y.com");
    assert_eq!(label, "alice@x.com \u{2194} bob@y.com");
}

#[test]
fn scope_short_label_many_participants() {
    let label = scope_short_label("gmail:alice@x.com|bob@y.com|carol@z.com");
    assert_eq!(label, "alice@x.com + 2 others");
}

#[test]
fn scope_short_label_non_gmail_returns_raw() {
    let label = scope_short_label("slack:#general");
    assert_eq!(label, "slack:#general");
}

#[test]
fn rewrite_summary_tags_delegates_to_rewrite_tags() {
    let ts = chrono::Utc.timestamp_millis_opt(1_700_000_000_000).unwrap();
    let input = SummaryComposeInput {
        summary_id: "sum:L1:rwttest",
        tree_kind: SummaryTreeKind::Source,
        tree_id: "t1",
        tree_scope: "gmail:alice@x.com",
        level: 1,
        child_ids: &["c1".to_string()],
        child_basenames: None,
        child_count: 1,
        time_range_start: ts,
        time_range_end: ts,
        sealed_at: ts,
        body: "summary body text",
    };
    let composed = compose_summary_md(&input);
    let file_bytes = composed.full.as_bytes();
    let new_tags = vec!["person/Alice-Smith".to_string(), "topic/Memory".to_string()];
    let rewritten = rewrite_summary_tags(file_bytes, &new_tags).unwrap();
    let rewritten_str = std::str::from_utf8(&rewritten).unwrap();
    assert!(rewritten_str.contains("  - person/Alice-Smith"));
    assert!(rewritten_str.contains("  - topic/Memory"));
    assert!(!rewritten_str.contains("tags: []"));
    assert!(rewritten_str.contains(&format!(
        "openhuman_core_version: {}",
        OPENHUMAN_CORE_VERSION
    )));
    assert!(rewritten_str.contains(&format!(
        "memory_artifact_format: {}",
        MEMORY_ARTIFACT_FORMAT
    )));
    assert!(rewritten_str.ends_with("summary body text"));
}

#[test]
fn rewrite_summary_tags_backfills_missing_provenance() {
    let file = b"---\nid: legacy\nkind: summary\ntags: []\naliases:\n  - legacy\n---\nlegacy body";
    let rewritten = rewrite_summary_tags(file, &["person/Alice".to_string()]).unwrap();
    let rewritten_str = std::str::from_utf8(&rewritten).unwrap();
    assert!(rewritten_str.contains(&format!(
        "openhuman_core_version: {}",
        OPENHUMAN_CORE_VERSION
    )));
    assert!(rewritten_str.contains(&format!(
        "memory_artifact_format: {}",
        MEMORY_ARTIFACT_FORMAT
    )));
    assert!(rewritten_str.ends_with("legacy body"));
}

use super::*;
use crate::memory::chunks::SourceKind;
use chrono::Utc;

fn meta(tags: &[&str]) -> Metadata {
    let mut m = Metadata::point_in_time(SourceKind::Chat, "x", "owner", Utc::now());
    m.tags = tags.iter().map(|s| s.to_string()).collect();
    m
}

#[test]
fn no_tags_neutral() {
    assert_eq!(score(&meta(&[])), 0.5);
    assert_eq!(score(&meta(&["unrelated"])), 0.5);
}

#[test]
fn sent_tag_high_score() {
    assert!((score(&meta(&["sent"])) - 0.6).abs() < 1e-6);
}

#[test]
fn stacking_capped_at_one() {
    // sent (0.6) + reply (0.5) + mention (0.2) = 1.3 → clamp to 1.0
    assert!((score(&meta(&["sent", "reply", "mention"])) - 1.0).abs() < 1e-6);
}

#[test]
fn reply_only() {
    assert!((score(&meta(&["reply"])) - 0.5).abs() < 1e-6);
}

#[test]
fn dm_plus_mention() {
    assert!((score(&meta(&["dm", "mention"])) - 0.5).abs() < 1e-6);
}

//! `search_entities` tests. Ported from OpenHuman's
//! `memory_tree::retrieval::search`, reseeding the entity index directly
//! instead of running the full ingest pipeline.

use super::*;
use crate::memory::retrieval::test_support::{index_entity_occurrence, test_config};
use crate::memory::score::extract::EntityKind;

/// Seed a handful of entity-index rows mimicking what ingest would produce for
/// one message mentioning two emails and a hashtag.
fn seed_entities(cfg: &crate::memory::config::MemoryConfig, node_id: &str) {
    index_entity_occurrence(
        cfg,
        "email:alice@example.com",
        EntityKind::Email,
        "alice@example.com",
        node_id,
        "leaf",
        1_700_000_000_000,
        None,
    );
    index_entity_occurrence(
        cfg,
        "email:bob@example.com",
        EntityKind::Email,
        "bob@example.com",
        node_id,
        "leaf",
        1_700_000_000_000,
        None,
    );
    index_entity_occurrence(
        cfg,
        "hashtag:launch-q2",
        EntityKind::Hashtag,
        "#launch-q2",
        node_id,
        "leaf",
        1_700_000_000_000,
        None,
    );
}

#[test]
fn empty_index_returns_empty_vec() {
    let (_tmp, cfg) = test_config();
    let matches = search_entities(&cfg, "alice", None, 10).unwrap();
    assert!(matches.is_empty());
}

#[test]
fn blank_query_returns_empty() {
    let (_tmp, cfg) = test_config();
    seed_entities(&cfg, "leaf-1");
    let matches = search_entities(&cfg, "   ", None, 10).unwrap();
    assert!(matches.is_empty());
}

#[test]
fn matches_on_entity_id_substring() {
    let (_tmp, cfg) = test_config();
    seed_entities(&cfg, "leaf-1");
    let matches = search_entities(&cfg, "alice", None, 10).unwrap();
    assert!(
        matches
            .iter()
            .any(|m| m.canonical_id == "email:alice@example.com"),
        "expected alice's canonical id; got {matches:?}"
    );
}

#[test]
fn matches_on_surface_substring() {
    let (_tmp, cfg) = test_config();
    seed_entities(&cfg, "leaf-1");
    // "example.com" appears in the surface form and the canonical id.
    let matches = search_entities(&cfg, "example.com", None, 10).unwrap();
    assert!(
        matches.iter().any(|m| m.canonical_id.contains("alice")),
        "surface-matched row must surface; got {matches:?}"
    );
}

#[test]
fn kind_filter_narrows_results() {
    let (_tmp, cfg) = test_config();
    seed_entities(&cfg, "leaf-1");
    let only_hashtags = search_entities(&cfg, "launch", Some(&[EntityKind::Hashtag]), 10).unwrap();
    assert!(only_hashtags
        .iter()
        .all(|m| matches!(m.kind, EntityKind::Hashtag)));
    assert!(!only_hashtags.is_empty());
}

#[test]
fn matches_aggregate_across_multiple_nodes() {
    let (_tmp, cfg) = test_config();
    // Same entity mentioned on two distinct nodes → mention_count >= 2.
    index_entity_occurrence(
        &cfg,
        "email:alice@example.com",
        EntityKind::Email,
        "alice@example.com",
        "leaf-a",
        "leaf",
        1_700_000_000_000,
        None,
    );
    index_entity_occurrence(
        &cfg,
        "email:alice@example.com",
        EntityKind::Email,
        "alice@example.com",
        "leaf-b",
        "leaf",
        1_700_000_000_001,
        None,
    );
    let matches = search_entities(&cfg, "alice", None, 10).unwrap();
    let alice = matches
        .iter()
        .find(|m| m.canonical_id == "email:alice@example.com")
        .expect("alice should be in matches");
    assert!(
        alice.mention_count >= 2,
        "expected >= 2 aggregated mentions, got {}",
        alice.mention_count
    );
}

