        mock.calls.load(Ordering::SeqCst),
        1,
        "a 500-wrapped monthly-quota refusal must not be retried"
    );
    assert!(out.entities.is_empty());
}

#[tokio::test]
async fn extract_retries_transient_provider_error() {
    // A transport/transient failure (no 4xx, no auth marker) must still exhaust
    // the retry budget before falling back.
    use async_trait::async_trait;
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::Arc;

    struct TransientProvider {
        calls: AtomicUsize,
    }
    #[async_trait]
    impl ChatProvider for TransientProvider {
        fn name(&self) -> &str {
            "test:transient"
        }
        async fn chat_for_json(&self, _p: &ChatPrompt) -> anyhow::Result<String> {
            self.calls.fetch_add(1, Ordering::SeqCst);
            Err(anyhow::anyhow!(
                "error sending request for url (https://api): connection refused"
            ))
        }
    }

    let mock = Arc::new(TransientProvider {
        calls: AtomicUsize::new(0),
    });
    let ex = LlmEntityExtractor::new(LlmExtractorConfig::default(), mock.clone());
    let out = ex.extract("some text").await.unwrap();

    assert_eq!(
        mock.calls.load(Ordering::SeqCst),
        3,
        "a transient error must still exhaust the retry budget"
    );
    assert!(out.entities.is_empty());
}

//! Shared deterministic [`QueueDelegates`] implementation for the queue tests.
//!
//! Compiled only under `#[cfg(test)]`. Records call counts so tests can assert
//! the pipeline shape (extract → append → seal), and exposes knobs for the
//! admission decision, the seal cascade, the stale-buffer list, and the
//! re-embed progress sequence.

use std::collections::VecDeque;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

use anyhow::Result;
use async_trait::async_trait;
use parking_lot::Mutex;

use crate::memory::config::MemoryConfig;
use crate::memory::queue::handlers::{
    AppendDecision, ExtractDecision, QueueDelegates, ReembedProgress, StaleBuffer,
};
use crate::memory::queue::types::{AppendTarget, NodeRef, SealDocumentPayload, SealPayload};

/// Observable call counters, cloneable so a test can read them after `drain`.
#[derive(Default)]
pub(crate) struct Counts {
    pub extract: AtomicUsize,
    pub append: AtomicUsize,
    pub seal: AtomicUsize,
    pub flush: AtomicUsize,
    pub seal_document: AtomicUsize,
    pub reembed: AtomicUsize,
}

pub(crate) struct RecordingDelegates {
    pub counts: Arc<Counts>,
    /// `extract_chunk` decision; `None` simulates a missing chunk row.
    pub extract: Option<ExtractDecision>,
    /// `append_node` decision; `None` simulates a missing node / archived tree.
    pub append: Option<AppendDecision>,
    /// `seal_level` follow-up parent (one-shot; consumed on first seal).
    pub seal_parent: Mutex<Option<SealPayload>>,
    /// Buffers `list_stale_buffers` returns.
    pub stale: Vec<StaleBuffer>,
    /// `reembed_batch` outcomes, consumed front-to-back; empties to `Covered`.
    pub reembed: Mutex<VecDeque<ReembedProgress>>,
    /// `active_signature` value.
    pub signature: String,
    /// `has_uncovered_reembed_work` answer.
    pub uncovered: bool,
}

impl RecordingDelegates {
    /// A default that admits every chunk into `slack:#eng`, seals once with no
    /// cascade, has no stale buffers, and reports a covered embedding space.
    pub fn admitting() -> Self {
        Self {
            counts: Arc::new(Counts::default()),
            extract: Some(ExtractDecision {
                kept: true,
                uses_document_subtree: false,
                tree_scope: "slack:#eng".into(),
            }),
            append: Some(AppendDecision {
                tree_id: "tree:slack".into(),
                should_seal: true,
            }),
            seal_parent: Mutex::new(None),
            stale: Vec::new(),
            reembed: Mutex::new(VecDeque::new()),
            signature: "provider=test;model=x;dims=3".into(),
            uncovered: false,
        }
    }
}

#[async_trait]
impl QueueDelegates for RecordingDelegates {
    async fn extract_chunk(
        &self,
        _config: &MemoryConfig,
        _chunk_id: &str,
    ) -> Result<Option<ExtractDecision>> {
        self.counts.extract.fetch_add(1, Ordering::Relaxed);
        Ok(self.extract.clone())
    }

    async fn append_node(
        &self,
        _config: &MemoryConfig,
        _node: &NodeRef,
        _target: &AppendTarget,
    ) -> Result<Option<AppendDecision>> {
        self.counts.append.fetch_add(1, Ordering::Relaxed);
        Ok(self.append.clone())
    }

    async fn seal_level(
        &self,
        _config: &MemoryConfig,
        _payload: &SealPayload,
    ) -> Result<Option<SealPayload>> {
        self.counts.seal.fetch_add(1, Ordering::Relaxed);
        Ok(self.seal_parent.lock().take())
    }

    async fn list_stale_buffers(
        &self,
        _config: &MemoryConfig,
        _max_age_secs: i64,
    ) -> Result<Vec<StaleBuffer>> {
        self.counts.flush.fetch_add(1, Ordering::Relaxed);
        Ok(self.stale.clone())
    }

    async fn seal_document(
        &self,
        _config: &MemoryConfig,
        _payload: &SealDocumentPayload,
    ) -> Result<()> {
        self.counts.seal_document.fetch_add(1, Ordering::Relaxed);
        Ok(())
    }

    async fn reembed_batch(
        &self,
        _config: &MemoryConfig,
        _signature: &str,
    ) -> Result<ReembedProgress> {
        self.counts.reembed.fetch_add(1, Ordering::Relaxed);
        Ok(self
            .reembed
            .lock()
            .pop_front()
            .unwrap_or(ReembedProgress::Covered))
    }

    fn active_signature(&self, _config: &MemoryConfig) -> String {
        self.signature.clone()
    }

    fn has_uncovered_reembed_work(&self, _config: &MemoryConfig, _signature: &str) -> Result<bool> {
        Ok(self.uncovered)
    }
}

//! Shared test fixtures for the retrieval unit tests.
//!
//! Seeds a small SQLite store under a `tempfile::TempDir` and exposes helpers
//! to insert chunks, scores, summary trees, and entity-index rows directly —
//! bypassing the full ingest/seal pipeline so each retrieval primitive can be
//! exercised against a hand-built fixture with inert (zero-vector) embeddings.

use chrono::{DateTime, TimeZone, Utc};
use tempfile::TempDir;

use crate::memory::chunks::{
    chunk_id, tree_active_signature, upsert_chunks, with_connection, Chunk, Metadata, SourceKind,
    SourceRef,
};
use crate::memory::config::MemoryConfig;
use crate::memory::score::extract::EntityKind;
use crate::memory::score::resolver::CanonicalEntity;
use crate::memory::score::signals::ScoreSignals;
use crate::memory::score::store::{index_entities, upsert_score, ScoreRow};
use crate::memory::tree::store::{
    insert_summary_tx, insert_tree, set_summary_embedding_for_signature,
};
use crate::memory::tree::{SummaryNode, Tree, TreeKind, TreeStatus};

/// A fresh config rooted at a throwaway tempdir. The returned [`TempDir`] must
/// be kept alive for the duration of the test (dropping it deletes the store).
pub fn test_config() -> (TempDir, MemoryConfig) {
    let tmp = TempDir::new().unwrap();
    let cfg = MemoryConfig::new(tmp.path());
    (tmp, cfg)
}

/// A fixed epoch-millis timestamp for deterministic fixtures.
pub fn fixed_ts() -> DateTime<Utc> {
    Utc.timestamp_millis_opt(1_700_000_000_000).unwrap()
}

/// Build a chat chunk with a deterministic id derived from its content.
pub fn sample_chunk(source: &str, seq: u32, content: &str) -> Chunk {
    sample_chunk_at(source, seq, content, fixed_ts())
}

/// Build a chat chunk at an explicit timestamp.
pub fn sample_chunk_at(source: &str, seq: u32, content: &str, ts: DateTime<Utc>) -> Chunk {
    Chunk {
        id: chunk_id(SourceKind::Chat, source, seq, content),
        content: content.to_string(),
        metadata: Metadata {
            source_kind: SourceKind::Chat,
            source_id: source.into(),
            owner: "alice".into(),
            timestamp: ts,
            time_range: (ts, ts),
            tags: vec![],
            source_ref: Some(SourceRef::new(format!("slack://{source}/{seq}"))),
            path_scope: None,
        },
        token_count: 20,
        seq_in_source: seq,
        created_at: ts,
        partial_message: false,
    }
}

/// Persist chunks to the store.
pub fn insert_chunks(cfg: &MemoryConfig, chunks: &[Chunk]) {
    upsert_chunks(cfg, chunks).unwrap();
}

/// Upsert a score row for a chunk with the given total.
pub fn insert_score(cfg: &MemoryConfig, chunk_id: &str, total: f32) {
    upsert_score(
        cfg,
        &ScoreRow {
            chunk_id: chunk_id.to_string(),
            total,
            signals: ScoreSignals::default(),
            dropped: false,
            reason: None,
            computed_at_ms: 0,
            llm_importance_reason: None,
        },
    )
    .unwrap();
}

/// Insert a tree row.
pub fn insert_tree_row(cfg: &MemoryConfig, tree: &Tree) {
    insert_tree(cfg, tree).unwrap();
}

/// Insert a summary node row (idempotent on primary key). Any `embedding` on
/// the node is written to the active-signature sidecar.
pub fn insert_summary(cfg: &MemoryConfig, node: &SummaryNode) {
    let sig = tree_active_signature(cfg);
    with_connection(cfg, |conn| {
        let tx = conn.unchecked_transaction()?;
        insert_summary_tx(&tx, node, &sig)?;
        tx.commit()?;
        Ok(())
    })
    .unwrap();
}

/// Write a summary's embedding to the active-signature sidecar table.
pub fn set_summary_embedding(cfg: &MemoryConfig, summary_id: &str, vec: &[f32]) {
    let sig = tree_active_signature(cfg);
    set_summary_embedding_for_signature(cfg, summary_id, &sig, vec).unwrap();
}

/// Index one entity occurrence against a node.
pub fn index_entity_occurrence(
    cfg: &MemoryConfig,
    canonical_id: &str,
    kind: EntityKind,
    surface: &str,
    node_id: &str,
    node_kind: &str,
    timestamp_ms: i64,
    tree_id: Option<&str>,
) {
    let entity = CanonicalEntity {
        canonical_id: canonical_id.to_string(),
        kind,
        surface: surface.to_string(),
        span_start: 0,
        span_end: 0,
        score: 1.0,
    };
    index_entities(cfg, &[entity], node_id, node_kind, timestamp_ms, tree_id).unwrap();
}

/// A minimal active source tree rooted at `scope`.
pub fn source_tree(id: &str, scope: &str, root_id: Option<&str>, max_level: u32) -> Tree {
    let ts = fixed_ts();
    Tree {
        id: id.into(),
        kind: TreeKind::Source,
        scope: scope.into(),
        root_id: root_id.map(|s| s.to_string()),
        max_level,
        status: TreeStatus::Active,
        created_at: ts,
        last_sealed_at: Some(ts),
    }
}

/// A summary node builder. `embedding` is `None` by default; set it before
/// inserting to populate the sidecar.
#[allow(clippy::too_many_arguments)]
pub fn summary_node(
    id: &str,
    tree_id: &str,
    level: u32,
    parent_id: Option<&str>,
    child_ids: &[&str],
    content: &str,
    ts: DateTime<Utc>,
) -> SummaryNode {
    SummaryNode {
        id: id.into(),
        tree_id: tree_id.into(),
        tree_kind: TreeKind::Source,
        level,
        parent_id: parent_id.map(|s| s.to_string()),
        child_ids: child_ids.iter().map(|s| s.to_string()).collect(),
        content: content.into(),
        token_count: 10,
        entities: vec![],
        topics: vec![],
        time_range_start: ts,
        time_range_end: ts,
        score: 0.5,
        sealed_at: ts,
        deleted: false,
        embedding: None,
        doc_id: None,
        version_ms: None,
    }
}

